solution:
import { useState } from 'react';

export function useColor(palette) {
  const [index, setIndex] = useState(0);
  return {
    color: palette[index],
    next: () => setIndex(i => (i + 1) % palette.length),
    prev: () => setIndex(i => (i - 1 + palette.length) % palette.length),
    index,
  };
}
